// redaction.openai_privacy_filter.command becomes argv[0] of an exec call in
// the pre-push OPF rewrite (see redact.ConfigurePrivacyFilter → newShellOut).
// It is therefore not ordinary configuration: whoever controls the string
// controls what Entire executes on the developer's machine.
//
// .entire/settings.json is version-controlled, so an ordinary pull request can
// carry a `command` pointing at a payload committed alongside it. A JSON
// settings diff does not read as executable to a reviewer, and neither the
// pre-push prompt (which never names the command) nor prompt_default="always"
// / non-TTY auto-run stands in the way.
//
// The boundary below is therefore ownership, not syntax: only the developer
// running the push may choose the binary. `command` is honored solely from
// .entire/settings.local.json, and only when that file is genuinely local —
// untracked in the index AND absent from HEAD. The filename alone proves
// nothing, because .gitignore does not apply to a path that is already
// tracked: `git add -f .entire/settings.local.json` commits it, and a fresh
// clone materializes it on disk with the attacker's content.
//
// Rejection is a downgrade, never an error: Command resets to "" and
// ConfigurePrivacyFilter falls back to the documented default of resolving
// "opf" on $PATH, which Go's exec.ErrDot protects against "." entries. If that
// binary is missing, the pre-push rewrite fails closed rather than pushing
// content the user believed OPF had scanned.
//
// localData is the raw .entire/settings.local.json bytes (nil when absent).
// Provenance is probed from it lazily, after the Command check, so a load that
// has no OPF command to gate does no extra JSON or git work.
func enforceOPFCommandTrust(ctx context.Context, s *EntireSettings, localSettingsPath string, localData []byte) {
	if s == nil || s.Redaction == nil || s.Redaction.OpenAIPrivacyFilter == nil {
		return
	}
	opf := s.Redaction.OpenAIPrivacyFilter
	if opf.Command == "" {
		return
	}
	reason := opfCommandUntrustedReason(ctx, localSettingsPath, localData)
	if reason == "" {
		return
	}

	logCtx := logging.WithComponent(ctx, "redaction")
	logging.Warn(logCtx, "ignoring openai_privacy_filter.command; falling back to \"opf\" on $PATH",
		slog.String("reason", reason),
		slog.String("ignored_command", opf.Command),
		slog.String("remediation", "set redaction.openai_privacy_filter.command in .entire/settings.local.json, and keep that file out of version control"),
	)
	opf.Command = ""
}

// opfCommandUntrustedReason returns why the effective OPF command may not be
// trusted, or "" when it is the developer's own choice.
func opfCommandUntrustedReason(ctx context.Context, localSettingsPath string, localData []byte) string {
	if !localSetsOPFCommand(localData) {
		return "it comes from the version-controlled project settings file"
	}
	versioned, err := pathIsVersioned(ctx, localSettingsPath)
	if err != nil {
		// Cannot prove the file is developer-owned, so do not trust it.
		// Outside a git repo there is no push and no OPF run, making this a
		// no-op in practice rather than a regression.
		return "its origin could not be verified as untracked: " + err.Error()
	}
	if versioned {
		return "the local settings file is itself tracked in git, so its contents can arrive through a pull request"
	}
	return ""
}

// localSetsOPFCommand reports whether the local override file explicitly sets
// redaction.openai_privacy_filter.command.
//
// Presence of the key is what matters, not the merged value: the project file
// and the local file may set the same string, and comparing effective values
// after the merge would misattribute that to the project layer. A malformed
// local file yields false, which is the safe direction — the merge itself
// fails separately with a parse error.
func localSetsOPFCommand(data []byte) bool {
	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		return false
	}
	_, ok := rawObject(rawObject(raw, "redaction"), "openai_privacy_filter")["command"]
	return ok
}

// rawObject returns parent[key] decoded as a JSON object, or nil when the key
// is absent or does not hold an object. Indexing the nil result is safe, so
// lookups can be chained without intermediate checks.
func rawObject(parent map[string]json.RawMessage, key string) map[string]json.RawMessage {
	v, ok := parent[key]
	if !ok {
		return nil
	}
	var out map[string]json.RawMessage
	if err := json.Unmarshal(v, &out); err != nil {
		return nil
	}
	return out
}

// versionedPaths memoizes pathIsVersioned for the process lifetime.
//
// settings.Load has no caching of its own and runs several times per hook
// invocation, so an unmemoized probe multiplied one git call into ~15 per
// commit — a measurable hook-latency regression for exactly the users who
// configured the feature. Whether a path is tracked cannot change inside a
// single hook process. Only successful determinations are cached: an error
// means "could not verify", and caching one observed under a cancelled context
// would poison later lookups that could have answered.
var (
	versionedPathsMu sync.Mutex
	versionedPaths   = map[string]bool{}
)

// pathIsVersioned reports whether path is tracked in the index or present in
// HEAD. Both matter and they fail independently: a path can be staged but
// never committed, or committed and later removed from the index.
//
// An error means "could not determine" (not a repository, git missing, path
// outside the worktree) and callers must treat it as untrusted rather than as
// a negative answer.
func pathIsVersioned(ctx context.Context, path string) (bool, error) {
	versionedPathsMu.Lock()
	cached, ok := versionedPaths[path]
	versionedPathsMu.Unlock()
	if ok {
		return cached, nil
	}

	versioned, err := probePathIsVersioned(ctx, path)
	if err != nil {
		return false, err
	}

	versionedPathsMu.Lock()
	versionedPaths[path] = versioned
	versionedPathsMu.Unlock()
	return versioned, nil
}

func probePathIsVersioned(ctx context.Context, path string) (bool, error) {
	dir := filepath.Dir(path)

	// --with-tree answers "in the index OR in HEAD" in one process, including
	// the committed-then-`git rm --cached` case that the index alone misses.
	out, err := gitexec.Run(ctx, dir, "ls-files", "-z", "--with-tree=HEAD", "--", path)
	if err == nil {
		return hasGitEntry(out), nil
	}

	// --with-tree fails on an unborn HEAD with the same exit code as "not a
	// repository", so disambiguate before trusting a narrower answer. Only the
	// failure path pays these extra calls; the common path stays at one.
	if _, headErr := gitexec.Run(ctx, dir, "rev-parse", "--verify", "--quiet", "HEAD"); headErr == nil {
		// HEAD resolves, so --with-tree failed for some other reason. Falling
		// back to the index alone could miss a HEAD-only entry and wrongly
		// report the file as untrusted-free, so report the failure instead.
		return false, err
	}

	// No commits yet: nothing can be in HEAD, so the index answer is complete.
	// Outside a repository this fails again and the caller treats the path as
	// unverifiable.
	out, plainErr := gitexec.Run(ctx, dir, "ls-files", "-z", "--", path)
	if plainErr != nil {
		return false, plainErr
	}
	return hasGitEntry(out), nil
}

// hasGitEntry reports whether a -z git listing named at least one path.
func hasGitEntry(out string) bool {
	return strings.Trim(out, "\x00") != ""
}
