// command is the developer's own. This exercises the unborn-HEAD fallback:
// `ls-files --with-tree=HEAD` fails there and the probe must not mistake that
// for an unverifiable path.
func TestOPFCommandTrust_UnbornHeadHonorsUntrackedLocal(t *testing.T) {
	t.Parallel()
	_, project, local := newOPFRepo(t) // InitRepo leaves no commits
