// than the git CLI. Beyond avoiding a subprocess, this removes a dependency on
// `git` being on $PATH — the population running GUI git clients, whose hooks
// do not inherit a shell profile, is precisely the one that needs an explicit
// `command` and would otherwise fail verification and lose it.
//
// path is always <worktreeRoot>/.entire/settings.local.json, so the worktree
// root is its grandparent and the repo-relative key is the known constant. No
// git call is needed to resolve either.
func probePathIsVersioned(_ context.Context, path string) (bool, error) {
	repo, err := gitrepo.OpenPath(filepath.Dir(filepath.Dir(path)))
	if err != nil {
		return false, fmt.Errorf("open repository: %w", err)
	}
	defer func() { _ = repo.Close() }()

	// Index. Catches a staged file that was never committed.
	idx, err := repo.Storer.Index()
	if err != nil {
		return false, fmt.Errorf("read index: %w", err)
	}
	if _, err := idx.Entry(indexKey); err == nil {
		return true, nil
	} else if !errors.Is(err, index.ErrEntryNotFound) {
		return false, fmt.Errorf("look up %s in index: %w", indexKey, err)
	}

